UML Generator.class_diagram:
classDiagram
    class User {
        +id
        +name
        +email
    }
    class Student {
        +takeExam()
        +viewResult()
    }
    class Teacher {
        +createQuestion()
        +scheduleExam()
        +reviewResult()
    }
    class Admin {
        +manageUser()
        +configureSettings()
    }
    class Exam {
        +startTime
        +duration
        +grade()
    }
    class Question {
        +text
        +type
        +score
    }
    User <|-- Student
    User <|-- Teacher
    User <|-- Admin
    Exam "*" -- "*" Question : contains
    Student "*" -- "*" Exam : takes
    Teacher "*" -- "*" Exam : schedules
    Exam "*" -- "1" Student : results

